{
  "title": "夜市的秘密",
  "scene": "你走进了一个灯火通明的夜市，霓虹灯闪烁着各种广告。市场里有很多机器人在忙碌，有的卖东西，有的打扫。你注意到一个角落里有一个穿着黑色风衣的人，他的眼睛里有奇怪的光芒，似乎是个黑客。旁边有一个巨大的广告牌，上面写着‘欢迎来到超科企业’。你听到有人说，‘超科企业最近在招募能破解他们系统的人。’",
  "goal": "找到进入超科企业的途径",
  "clue": "黑客的眼睛光芒和夜市的广告牌",
  "choices": [
    {
      "id": "A",
      "text": "和黑衣人交谈",
      "outcome": "他告诉你他是超科企业的测试员，可以带你进去，但需要你帮他找到一个特别的程序。你同意了，他给了你一张进入企业的通行证。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "直接走向超科企业的大门",
      "outcome": "你轻松地找到了大门，但守卫严格检查了你的身份。因为没有特别的邀请码，你被礼貌地拒绝了。你只能返回夜市寻找其他线索。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "去找夜市里的机器人帮忙",
      "outcome": "一个友好的机器人告诉你，超科企业确实需要特殊的邀请码才能进入，但它可以带你去找一个能提供帮助的秘密入口。你跟着机器人，成功找到了一条通往企业内部的小路。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
